// --------------- Parser ---------------

pub struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
    line: usize,
}

#[derive(Debug)]
pub struct ParseError {
    pub msg: String,
    pub line: usize,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} at line {}", self.msg, self.line)
    }
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str) -> Self {
        Parser { src: src.as_bytes(), pos: 0, line: 1 }
    }

    fn err<T>(&self, msg: impl Into<String>) -> Result<T, ParseError> {
        Err(ParseError { msg: msg.into(), line: self.line })
    }

    fn peek(&self) -> Option<u8> { self.src.get(self.pos).copied() }
    fn advance(&mut self) -> Option<u8> {
        let b = self.src.get(self.pos).copied()?;
        self.pos += 1;
        if b == b'\n' { self.line += 1; }
        Some(b)
    }

    fn skip_ws_and_comments(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\r') | Some(b'\n') => { self.advance(); }
                Some(b'#') => {
                    while let Some(b) = self.peek() {
                        if b == b'\n' { break; }
                        self.advance();
                    }
                }
                _ => break,
            }
        }
    }

    fn skip_inline_ws(&mut self) {
        while matches!(self.peek(), Some(b' ') | Some(b'\t')) { self.advance(); }
    }

    pub fn parse(&mut self) -> Result<Value, ParseError> {
        let mut root: BTreeMap<String, Value> = BTreeMap::new();
        // Current table where non-qualified assignments go.
        // Path of keys into root.
        let mut cur_path: Vec<String> = Vec::new();

        loop {
            self.skip_ws_and_comments();
            if self.peek().is_none() { break; }

            if self.peek() == Some(b'[') {
                // Header: either [table.path] or [[array.of.tables]]
                self.advance();
                let is_array = self.peek() == Some(b'[');
                if is_array { self.advance(); }
                self.skip_inline_ws();
                let path = self.parse_key_path()?;
                self.skip_inline_ws();
                if self.peek() != Some(b']') { return self.err("expected `]` in table header"); }
                self.advance();
                if is_array {
                    if self.peek() != Some(b']') { return self.err("expected `]]` in array-of-tables header"); }
                    self.advance();
                }
                // trailing whitespace/comment until newline
                self.skip_trailing_to_newline()?;

                if is_array {
                    // Navigate/create up to the parent, then create new table in array.
                    let (parent_path, last) = path.split_at(path.len() - 1);
                    let parent = navigate_or_create_table(&mut root, parent_path)?;
                    let key = last[0].clone();
                    let arr = parent.entry(key).or_insert_with(|| Value::Array(Vec::new()));
                    match arr {
                        Value::Array(vs) => {
                            vs.push(Value::Table(BTreeMap::new()));
                        }
                        _ => return self.err("expected array of tables"),
                    }
                    // Current path points to the newly added table.
                    cur_path = path.clone();
                } else {
                    // For normal tables, ensure path exists, and make it current.
                    navigate_or_create_table(&mut root, &path)?;
                    cur_path = path;
                }
            } else {
                // key = value
                self.skip_inline_ws();
                let key_path = self.parse_key_path()?;
                self.skip_inline_ws();
                if self.peek() != Some(b'=') {
                    return self.err(format!("expected `=` after key, found {:?}",
                        self.peek().map(|b| b as char)));
                }
                self.advance();
                self.skip_inline_ws();
                let value = self.parse_value()?;
                self.skip_trailing_to_newline()?;

                // Store at cur_path + key_path. The last element is the assigned key; intermediate are tables.
                let (prefix, last) = key_path.split_at(key_path.len() - 1);
                let mut full_prefix: Vec<String> = cur_path.clone();
                full_prefix.extend_from_slice(prefix);
                let tbl = navigate_or_create_table_for_cur(&mut root, &cur_path, prefix)?;
                // Alternative: navigate from root via full_prefix.
                let _ = tbl;
                let full_prefix_v: Vec<String> = cur_path.iter().chain(prefix.iter()).cloned().collect();
                let parent = navigate_or_create_table(&mut root, &full_prefix_v)?;
                if parent.contains_key(&last[0]) {
                    return self.err(format!("duplicate key `{}`", last[0]));
                }
                parent.insert(last[0].clone(), value);
            }
        }

        Ok(Value::Table(root))
    }

    fn skip_trailing_to_newline(&mut self) -> Result<(), ParseError> {
        self.skip_inline_ws();
        match self.peek() {
            None => Ok(()),
            Some(b'\n') => { self.advance(); Ok(()) }
            Some(b'\r') => {
                self.advance();
                if self.peek() == Some(b'\n') { self.advance(); }
                Ok(())
            }
            Some(b'#') => {
                while let Some(b) = self.peek() {
                    if b == b'\n' { break; }
                    self.advance();
                }
                Ok(())
            }
            Some(b) => self.err(format!("unexpected char after value: {:?}", b as char)),
        }
    }

    fn parse_key_path(&mut self) -> Result<Vec<String>, ParseError> {
        let mut parts = Vec::new();
        loop {
            self.skip_inline_ws();
            let key = self.parse_single_key()?;
            parts.push(key);
            self.skip_inline_ws();
            if self.peek() == Some(b'.') {
                self.advance();
                continue;
            } else {
                break;
            }
        }
        Ok(parts)
    }

    fn parse_single_key(&mut self) -> Result<String, ParseError> {
        match self.peek() {
            Some(b'"') => {
                self.advance();
                self.parse_basic_string_body(b'"')
            }
            Some(b'\'') => {
                self.advance();
                self.parse_literal_string_body(b'\'')
            }
            _ => {
                // bare key
                let start = self.pos;
                while let Some(b) = self.peek() {
                    if b.is_ascii_alphanumeric() || b == b'_' || b == b'-' {
                        self.advance();
                    } else {
                        break;
                    }
                }
                if self.pos == start {
                    return self.err(format!("expected an equals, found an identifier"));
                }
                let s = std::str::from_utf8(&self.src[start..self.pos])
                    .map_err(|_| ParseError { msg: "invalid utf8 in key".into(), line: self.line })?;
                Ok(s.to_string())
            }
        }
    }

    fn parse_value(&mut self) -> Result<Value, ParseError> {
        self.skip_inline_ws();
        match self.peek() {
            Some(b'"') => {
                // Basic string (maybe multi-line)
                if self.src.get(self.pos..self.pos+3) == Some(b"\"\"\"") {
                    self.pos += 3;
                    // skip one immediate newline after """
                    if self.peek() == Some(b'\n') { self.advance(); }
                    else if self.peek() == Some(b'\r') { self.advance(); if self.peek() == Some(b'\n') { self.advance(); } }
                    self.parse_multiline_basic_string_body()
                } else {
                    self.advance();
                    let s = self.parse_basic_string_body(b'"')?;
                    Ok(Value::String(s))
                }
            }
            Some(b'\'') => {
                if self.src.get(self.pos..self.pos+3) == Some(b"'''") {
                    self.pos += 3;
                    if self.peek() == Some(b'\n') { self.advance(); }
                    else if self.peek() == Some(b'\r') { self.advance(); if self.peek() == Some(b'\n') { self.advance(); } }
                    self.parse_multiline_literal_string_body()
                } else {
                    self.advance();
                    let s = self.parse_literal_string_body(b'\'')?;
                    Ok(Value::String(s))
                }
            }
            Some(b'[') => {
                self.advance();
                let mut arr = Vec::new();
                loop {
                    self.skip_ws_and_comments();
                    if self.peek() == Some(b']') { self.advance(); break; }
                    let v = self.parse_value()?;
                    arr.push(v);
                    self.skip_ws_and_comments();
                    if self.peek() == Some(b',') { self.advance(); self.skip_ws_and_comments(); }
                    else if self.peek() == Some(b']') { self.advance(); break; }
                    else { return self.err("expected `,` or `]` in array"); }
                }
                Ok(Value::Array(arr))
            }
            Some(b'{') => {
                self.advance();
                let mut tbl = BTreeMap::new();
                loop {
                    self.skip_inline_ws();
                    if self.peek() == Some(b'}') { self.advance(); break; }
                    let kp = self.parse_key_path()?;
                    self.skip_inline_ws();
                    if self.peek() != Some(b'=') { return self.err("expected `=` in inline table"); }
                    self.advance();
                    self.skip_inline_ws();
                    let v = self.parse_value()?;
                    // Insert via key path
                    let (pref, last) = kp.split_at(kp.len() - 1);
                    let parent = navigate_or_create_table_mut(&mut tbl, pref)?;
                    parent.insert(last[0].clone(), v);
                    self.skip_inline_ws();
                    if self.peek() == Some(b',') { self.advance(); }
                    else if self.peek() == Some(b'}') { self.advance(); break; }
                    else { return self.err("expected `,` or `}` in inline table"); }
                }
                Ok(Value::Table(tbl))
            }
            Some(b't') | Some(b'f') => {
                if self.src[self.pos..].starts_with(b"true") {
                    self.pos += 4;
                    Ok(Value::Boolean(true))
                } else if self.src[self.pos..].starts_with(b"false") {
                    self.pos += 5;
                    Ok(Value::Boolean(false))
                } else {
                    self.err("expected boolean")
                }
            }
            Some(b) if b == b'-' || b == b'+' || b.is_ascii_digit() => {
                let start = self.pos;
                if b == b'-' || b == b'+' { self.advance(); }
                while let Some(bb) = self.peek() {
                    if bb.is_ascii_digit() || bb == b'_' { self.advance(); }
                    else { break; }
                }
                let s: String = std::str::from_utf8(&self.src[start..self.pos])
                    .map_err(|_| ParseError { msg: "bad number utf8".into(), line: self.line })?
                    .chars().filter(|c| *c != '_').collect();
                let n: i64 = s.parse().map_err(|_| ParseError {
                    msg: format!("invalid integer {:?}", s), line: self.line,
                })?;
                Ok(Value::Integer(n))
            }
            _ => self.err("expected a value"),
        }
    }

    fn parse_basic_string_body(&mut self, quote: u8) -> Result<String, ParseError> {
        let mut out = String::new();
        loop {
            let b = self.peek().ok_or_else(|| ParseError {
                msg: "unterminated string".into(), line: self.line,
            })?;
            if b == quote { self.advance(); return Ok(out); }
            if b == b'\n' { return self.err("newline in basic string"); }
            if b == b'\\' {
                self.advance();
                let c = self.peek().ok_or_else(|| ParseError {
                    msg: "bad escape".into(), line: self.line,
                })?;
                match c {
                    b'\\' => { out.push('\\'); self.advance(); }
                    b'"' => { out.push('"'); self.advance(); }
                    b'\'' => { out.push('\''); self.advance(); }
                    b'n' => { out.push('\n'); self.advance(); }
                    b'r' => { out.push('\r'); self.advance(); }
                    b't' => { out.push('\t'); self.advance(); }
                    b'b' => { out.push('\x08'); self.advance(); }
                    b'f' => { out.push('\x0c'); self.advance(); }
                    b'0' => { out.push('\0'); self.advance(); }
                    b'u' | b'U' => {
                        self.advance();
                        let n = if c == b'u' { 4 } else { 8 };
                        let hex = std::str::from_utf8(&self.src[self.pos..self.pos + n])
                            .map_err(|_| ParseError { msg: "bad unicode escape".into(), line: self.line })?;
                        let code = u32::from_str_radix(hex, 16)
                            .map_err(|_| ParseError { msg: "bad unicode escape".into(), line: self.line })?;
                        if let Some(ch) = char::from_u32(code) { out.push(ch); }
                        self.pos += n;
                    }
                    _ => return self.err("bad escape"),
                }
            } else {
                out.push(b as char);
                self.advance();
            }
        }
    }

    fn parse_multiline_basic_string_body(&mut self) -> Result<Value, ParseError> {
        let mut out = String::new();
        loop {
            if self.src.get(self.pos..self.pos+3) == Some(b"\"\"\"") {
                self.pos += 3;
                // Could be followed by one or two extra " at end
                if self.peek() == Some(b'"') { out.push('"'); self.advance();
                    if self.peek() == Some(b'"') { out.push('"'); self.advance(); }
                }
                return Ok(Value::String(out));
            }
            let b = self.peek().ok_or_else(|| ParseError {
                msg: "unterminated multiline string".into(), line: self.line,
            })?;
            if b == b'\\' {
                self.advance();
                let c = self.peek().ok_or_else(|| ParseError {
                    msg: "bad escape".into(), line: self.line,
                })?;
                match c {
                    b'\\' => { out.push('\\'); self.advance(); }
                    b'"' => { out.push('"'); self.advance(); }
                    b'\'' => { out.push('\''); self.advance(); }
                    b'n' => { out.push('\n'); self.advance(); }
                    b'r' => { out.push('\r'); self.advance(); }
                    b't' => { out.push('\t'); self.advance(); }
                    b'\n' | b' ' | b'\t' | b'\r' => {
                        // line-ending backslash: trim whitespace
                        while matches!(self.peek(), Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r')) {
                            self.advance();
                        }
                    }
                    _ => return self.err("bad escape"),
                }
            } else {
                out.push(b as char);
                self.advance();
            }
        }
    }

    fn parse_literal_string_body(&mut self, quote: u8) -> Result<String, ParseError> {
        let mut out = String::new();
        loop {
            let b = self.peek().ok_or_else(|| ParseError {
                msg: "unterminated literal string".into(), line: self.line,
            })?;
            if b == quote { self.advance(); return Ok(out); }
            if b == b'\n' { return self.err("newline in literal string"); }
            out.push(b as char);
            self.advance();
        }
    }

    fn parse_multiline_literal_string_body(&mut self) -> Result<Value, ParseError> {
        let mut out = String::new();
        loop {
            if self.src.get(self.pos..self.pos+3) == Some(b"'''") {
                self.pos += 3;
                if self.peek() == Some(b'\'') { out.push('\''); self.advance();
                    if self.peek() == Some(b'\'') { out.push('\''); self.advance(); }
                }
                return Ok(Value::String(out));
            }
            let b = self.peek().ok_or_else(|| ParseError {
                msg: "unterminated multiline literal string".into(), line: self.line,
            })?;
            out.push(b as char);
            self.advance();
        }
    }
}

fn navigate_or_create_table_for_cur<'a>(
    _root: &'a mut BTreeMap<String, Value>,
    _cur: &[String],
    _prefix: &[String],
) -> Result<&'a mut BTreeMap<String, Value>, ParseError> {
    unreachable!()
}

fn navigate_or_create_table<'a>(
    root: &'a mut BTreeMap<String, Value>,
    path: &[String],
) -> Result<&'a mut BTreeMap<String, Value>, ParseError> {
    let mut cur: &mut BTreeMap<String, Value> = root;
    for part in path {
        let entry = cur.entry(part.clone()).or_insert_with(|| Value::Table(BTreeMap::new()));
        match entry {
            Value::Table(t) => { cur = t; }
            Value::Array(arr) => {
                // For array of tables, navigate into the *last* table.
                let last = arr.last_mut().ok_or_else(|| ParseError {
                    msg: "empty array of tables".into(), line: 0,
                })?;
                match last {
                    Value::Table(t) => cur = t,
                    _ => return Err(ParseError { msg: "array element not a table".into(), line: 0 }),
                }
            }
            _ => return Err(ParseError { msg: format!("key `{}` is not a table", part), line: 0 }),
        }
    }
    Ok(cur)
}

fn navigate_or_create_table_mut<'a>(
    root: &'a mut BTreeMap<String, Value>,
    path: &[String],
) -> Result<&'a mut BTreeMap<String, Value>, ParseError> {
    navigate_or_create_table(root, path)
}

pub fn parse(src: &str) -> Result<Value, ParseError> {
    Parser::new(src).parse()
}

// --------------- Emitter (pier-compatible style) ---------------

fn is_bare_key(s: &str) -> bool {
    !s.is_empty() && s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

fn emit_key(s: &str) -> String {
    if is_bare_key(s) {
        s.to_string()
    } else {
        // Prefer basic string quoting for non-bare keys.
        emit_basic_string(s)
    }
}

fn emit_basic_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04X}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn emit_string_value(s: &str) -> String {
    // Decide: literal single-quoted (preferred), basic double-quoted, or multi-line literal ''' for strings with \n.
    let contains_newline = s.contains('\n');
    let contains_single = s.contains('\'');
    let contains_ctrl = s.chars().any(|c| (c as u32) < 0x20 && c != b'\n' as u32 as char && c != b'\t' as u32 as char);

    if contains_newline {
        // Use ''' ... ''' multi-line literal, if the body doesn't contain ''' exactly.
        if !s.contains("'''") && !contains_ctrl_nontab_nonnewline(s) {
            let mut out = String::from("'''\n");
            out.push_str(s);
            out.push_str("'''");
            return out;
        }
        // Fallback to basic multi-line or escaped basic string.
        return emit_basic_string(s);
    }

    if !contains_single && !contains_ctrl {
        let mut out = String::from("'");
        out.push_str(s);
        out.push('\'');
        return out;
    }

    emit_basic_string(s)
}

fn contains_ctrl_nontab_nonnewline(s: &str) -> bool {
    s.chars().any(|c| (c as u32) < 0x20 && c != '\n' && c != '\t' && c != '\r')
}

pub struct Emitter {
    out: String,
}

impl Emitter {
    pub fn new() -> Self { Emitter { out: String::new() } }
    pub fn finish(self) -> String { self.out }

    pub fn emit_table(&mut self, path: &[&str], table: &BTreeMap<String, Value>, keys_order: &[&str]) {
        // Header:
        if !path.is_empty() {
            let hdr = path.iter().map(|p| emit_key(p)).collect::<Vec<_>>().join(".");
            let _ = writeln!(self.out, "[{}]", hdr);
        }
        // Emit keys in requested order, then anything else.
        let mut emitted = std::collections::HashSet::new();
        for k in keys_order {
            if let Some(v) = table.get(*k) {
                self.emit_kv(k, v);
                emitted.insert(k.to_string());
            }
        }
        for (k, v) in table {
            if !emitted.contains(k) {
                // Don't emit sub-tables inline here; they come as separate headers.
                if matches!(v, Value::Table(_)) { continue; }
                self.emit_kv(k, v);
            }
        }
    }

    fn emit_kv(&mut self, k: &str, v: &Value) {
        match v {
            Value::String(s) => {
                let sv = emit_string_value(s);
                let _ = writeln!(self.out, "{} = {}", emit_key(k), sv);
            }
            Value::Integer(i) => {
                let _ = writeln!(self.out, "{} = {}", emit_key(k), i);
            }
            Value::Boolean(b) => {
                let _ = writeln!(self.out, "{} = {}", emit_key(k), b);
            }
            Value::Array(a) => {
                self.emit_array_kv(k, a);
            }
            Value::Table(_) => { /* handled separately */ }
        }
    }

    fn emit_array_kv(&mut self, k: &str, a: &[Value]) {
        match a.len() {
            0 => { let _ = writeln!(self.out, "{} = []", emit_key(k)); }
            1 => {
                let v = emit_array_inline_single(&a[0]);
                let _ = writeln!(self.out, "{} = [{}]", emit_key(k), v);
            }
            _ => {
                let _ = writeln!(self.out, "{} = [", emit_key(k));
                for v in a {
                    let vs = emit_array_inline_single(v);
                    let _ = writeln!(self.out, "    {},", vs);
                }
                let _ = writeln!(self.out, "]");
            }
        }
    }
}

fn emit_array_inline_single(v: &Value) -> String {
    match v {
        Value::String(s) => emit_string_value(s),
        Value::Integer(i) => i.to_string(),
        Value::Boolean(b) => b.to_string(),
        _ => "???".to_string(),
    }
}
