#[derive(Debug)]
pub enum LoadError {
    Io(PathBuf, std::io::Error),
    Toml(PathBuf, String),
    Shape(PathBuf, String),
    NotFound,
}

pub fn default_config_path() -> Option<PathBuf> {
    // $PIER_CONFIG_PATH env
    if let Ok(v) = std::env::var("PIER_CONFIG_PATH") {
        if !v.is_empty() { return Some(PathBuf::from(v)); }
    }
    // pier.toml in cwd
    if let Ok(cwd) = std::env::current_dir() {
        let p = cwd.join("pier.toml");
        if p.exists() { return Some(p); }
    }
    let xdg_cfg = std::env::var("XDG_CONFIG_HOME").ok()
        .filter(|s| !s.is_empty())
        .map(PathBuf::from)
        .or_else(|| std::env::var("HOME").ok().map(|h| PathBuf::from(h).join(".config")));
    if let Some(ref xdg) = xdg_cfg {
        let candidates = [
            xdg.join("pier/config.toml"),
            xdg.join("pier/config"),
            xdg.join("pier.toml"),
        ];
        for c in &candidates {
            if c.exists() { return Some(c.clone()); }
        }
    }
    if let Ok(home) = std::env::var("HOME") {
        let home = PathBuf::from(home);
        let candidates = [home.join(".pier.toml"), home.join(".pier")];
        for c in &candidates {
            if c.exists() { return Some(c.clone()); }
        }
    }
    None
}

pub fn load_from(path: &Path) -> Result<Config, LoadError> {
    let contents = std::fs::read_to_string(path)
        .map_err(|e| LoadError::Io(path.to_path_buf(), e))?;
    let val = toml_val::parse(&contents)
        .map_err(|e| LoadError::Toml(path.to_path_buf(), e.to_string()))?;
    build_config(path, val)
}

pub fn build_config(path: &Path, val: Value) -> Result<Config, LoadError> {
    let tbl = match &val {
        Value::Table(t) => t.clone(),
        _ => return Err(LoadError::Shape(path.to_path_buf(), "root is not a table".into())),
    };

    let mut scripts = BTreeMap::new();
    if let Some(Value::Table(s)) = tbl.get("scripts") {
        for (k, v) in s {
            match v {
                Value::Table(st) => {
                    let command = match st.get("command") {
                        Some(Value::String(s)) => s.clone(),
                        Some(_) => return Err(LoadError::Shape(
                            path.to_path_buf(),
                            format!("invalid type: expected string for key `scripts.{}.command`", k),
                        )),
                        None => return Err(LoadError::Shape(
                            path.to_path_buf(),
                            format!("missing `command` for key `scripts.{}`", k),
                        )),
                    };
