    let tbl = match &val {
        Value::Table(t) => t.clone(),
        _ => return Err(LoadError::Shape(path.to_path_buf(), "root is not a table".into())),
    };

    let mut scripts = BTreeMap::new();
    if let Some(Value::Table(s)) = tbl.get("scripts") {
        for (k, v) in s {
            match v {
                Value::Table(st) => {
                    let command = match st.get("command") {
                        Some(Value::String(s)) => s.clone(),
                        Some(_) => return Err(LoadError::Shape(
                            path.to_path_buf(),
                            format!("invalid type: expected string for key `scripts.{}.command`", k),
                        )),
                        None => return Err(LoadError::Shape(
                            path.to_path_buf(),
                            format!("missing `command` for key `scripts.{}`", k),
                        )),
                    };
                    let description = match st.get("description") {
                        Some(Value::String(s)) => Some(s.clone()),
                        None => None,
                        Some(_) => return Err(LoadError::Shape(
                            path.to_path_buf(),
                            format!("invalid type for `scripts.{}.description`", k),
                        )),
                    };
                    let tags = match st.get("tags") {
                        Some(Value::Array(a)) => {
                            let mut v = Vec::with_capacity(a.len());
                            for e in a {
                                if let Value::String(s) = e { v.push(s.clone()); }
                                else {
                                    return Err(LoadError::Shape(
                                        path.to_path_buf(),
                                        format!("invalid tag value for `scripts.{}.tags`", k),
                                    ));
                                }
                            }
                            Some(v)
                        }
                        None => None,
                        Some(_) => return Err(LoadError::Shape(
                            path.to_path_buf(),
                            format!("invalid type for `scripts.{}.tags`", k),
                        )),
                    };
                    scripts.insert(k.clone(), Script {
                        alias: k.clone(), command, description, tags, _unused: (),
                    });
                }
                _ => {
                    return Err(LoadError::Shape(
                        path.to_path_buf(),
                        format!("invalid type: string {:?}, expected struct Script for key `scripts.{}`",
                                as_display(v), k),
                    ));
                }
            }
        }
    }

    let defaults = if let Some(Value::Table(d)) = tbl.get("default") {
        let interpreter = match d.get("interpreter") {
            None => None,
            Some(Value::Array(a)) => {
                let mut v = Vec::new();
                for e in a {
                    if let Value::String(s) = e { v.push(s.clone()); }
                    else {
                        return Err(LoadError::Shape(
                            path.to_path_buf(),
                            "invalid interpreter element".into(),
                        ));
                    }
                }
                Some(v)
            }
            Some(other) => {
                return Err(LoadError::Shape(
                    path.to_path_buf(),
                    format!("invalid type: {} \"{}\", expected a sequence for key `default.interpreter`",
                            type_name(other), as_display(other)),
                ));
            }
        };
        let command_width = match d.get("command_width") {
            None => None,
            Some(Value::Integer(i)) => Some(*i),
            Some(_) => return Err(LoadError::Shape(
                path.to_path_buf(),
                "invalid command_width".into(),
            )),
        };
        Defaults { interpreter, command_width }
    } else {
        Defaults { interpreter: None, command_width: None }
    };

    Ok(Config {
        scripts,
        defaults,
        raw: val,
        path: path.to_path_buf(),
    })
}

fn type_name(v: &Value) -> &'static str {
    match v {
        Value::String(_) => "string",
        Value::Integer(_) => "integer",
        Value::Boolean(_) => "boolean",
        Value::Array(_) => "sequence",
        Value::Table(_) => "table",
    }
}
fn as_display(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Integer(i) => i.to_string(),
        Value::Boolean(b) => b.to_string(),
        Value::Array(_) => "[...]".into(),
        Value::Table(_) => "{...}".into(),
    }
}

// ---- serialization in pier's style ----

pub fn serialize(cfg: &Config) -> String {
    let mut e = toml_val::Emitter::new();
    let mut first = true;

    // Script tables first, alphabetically.
    let scripts_sorted: Vec<&Script> = cfg.scripts.values().collect();
    for s in &scripts_sorted {
        if !first { /* blank line separator */ e = {
            let mut s = e.finish();
            s.push('\n');
            let mut e2 = toml_val::Emitter::new();
            // We can't easily re-inject; use a different approach with plain buffer.
            let _ = s;
            e2
        }; }
        first = false;
        let _ = s;
    }
    // That approach is awkward; do custom formatting instead.
    let _ = e;

    let mut out = String::new();
    let mut first = true;
    for s in cfg.scripts.values() {
        if !first { out.push('\n'); }
        first = false;
        out.push_str(&format!("[scripts.{}]\n", toml_val::emit_key_pub(&s.alias)));
        out.push_str(&format!("command = {}\n", toml_val::emit_string_pub(&s.command)));
        if let Some(d) = &s.description {
            out.push_str(&format!("description = {}\n", toml_val::emit_string_pub(d)));
        }
        if let Some(tags) = &s.tags {
            out.push_str(&toml_val::emit_string_array_pub("tags", tags));
        }
    }
    // Default section (always emitted).
    if !first { out.push('\n'); }
    out.push_str("[default]\n");
    if let Some(ref interp) = cfg.defaults.interpreter {
        out.push_str(&toml_val::emit_string_array_pub("interpreter", interp));
    }
    if let Some(w) = cfg.defaults.command_width {
        out.push_str(&format!("command_width = {}\n", w));
    }
    out
}
