// Minimal TOML parser/emitter for pier's config schema.

use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub enum Value {
    String(String),
    Integer(i64),
    Boolean(bool),
    Array(Vec<Value>),
    Table(BTreeMap<String, Value>),
}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::String(_) => "string",
            Value::Integer(_) => "integer",
            Value::Boolean(_) => "boolean",
            Value::Array(_) => "sequence",
            Value::Table(_) => "table",
        }
    }
    pub fn display_inline(&self) -> String {
        match self {
            Value::String(s) => format!("\"{}\"", s),
            Value::Integer(i) => i.to_string(),
            Value::Boolean(b) => b.to_string(),
            Value::Array(_) => "[...]".into(),
            Value::Table(_) => "{...}".into(),
        }
    }
}

// ---- Parser ----

pub struct ParseError {
    pub msg: String,
    pub line: usize,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} at line {}", self.msg, self.line)
    }
}

struct P<'a> {
    s: &'a [u8],
    i: usize,
    line: usize,
}

impl<'a> P<'a> {
    fn new(s: &'a str) -> Self { P { s: s.as_bytes(), i: 0, line: 1 } }
    fn peek(&self) -> Option<u8> { self.s.get(self.i).copied() }
    fn peek_at(&self, off: usize) -> Option<u8> { self.s.get(self.i + off).copied() }
    fn bump(&mut self) -> Option<u8> {
        let b = self.peek()?;
        self.i += 1;
        if b == b'\n' { self.line += 1; }
        Some(b)
    }
    fn err<T>(&self, msg: impl Into<String>) -> Result<T, ParseError> {
        Err(ParseError { msg: msg.into(), line: self.line })
    }
    fn eat_inline_ws(&mut self) {
        while matches!(self.peek(), Some(b' ') | Some(b'\t')) { self.bump(); }
    }
    fn eat_ws_and_comments(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') => { self.bump(); }
                Some(b'#') => {
                    while let Some(b) = self.peek() {
                        if b == b'\n' { break; }
                        self.bump();
                    }
                }
                _ => break,
            }
        }
    }
    fn eat_line_end(&mut self) -> Result<(), ParseError> {
        self.eat_inline_ws();
        match self.peek() {
            None => Ok(()),
            Some(b'\n') => { self.bump(); Ok(()) }
            Some(b'\r') => {
                self.bump();
                if self.peek() == Some(b'\n') { self.bump(); }
                Ok(())
            }
            Some(b'#') => {
                while let Some(b) = self.peek() {
                    if b == b'\n' { break; }
                    self.bump();
                }
                Ok(())
            }
            Some(b) => self.err(format!("unexpected char {:?}", b as char)),
        }
    }
}

pub fn parse(src: &str) -> Result<Value, ParseError> {
    let mut p = P::new(src);
    let mut root: BTreeMap<String, Value> = BTreeMap::new();
    let mut cur_path: Vec<String> = Vec::new();

    loop {
        p.eat_ws_and_comments();
        if p.peek().is_none() { break; }

        if p.peek() == Some(b'[') {
            p.bump();
            let is_array = p.peek() == Some(b'[');
            if is_array { p.bump(); }
            p.eat_inline_ws();
            let path = parse_key_path(&mut p)?;
            p.eat_inline_ws();
            if p.peek() != Some(b']') { return p.err("expected `]`"); }
            p.bump();
            if is_array {
                if p.peek() != Some(b']') { return p.err("expected `]]`"); }
                p.bump();
            }
            p.eat_line_end()?;
            if is_array {
                let (pref, last) = path.split_at(path.len() - 1);
                let parent = navigate_or_create_table(&mut root, pref)?;
                let arr = parent.entry(last[0].clone()).or_insert_with(|| Value::Array(Vec::new()));
                if let Value::Array(v) = arr {
                    v.push(Value::Table(BTreeMap::new()));
                } else {
                    return p.err("array of tables conflict");
                }
                cur_path = path;
            } else {
                navigate_or_create_table(&mut root, &path)?;
                cur_path = path;
            }
        } else {
            p.eat_inline_ws();
            let kp = parse_key_path(&mut p)?;
            p.eat_inline_ws();
            if p.peek() != Some(b'=') {
                return Err(ParseError {
                    msg: "expected an equals, found an identifier".into(),
                    line: p.line,
                });
            }
            p.bump();
            p.eat_inline_ws();
            let val = parse_value(&mut p)?;
            p.eat_line_end()?;
            let (pref, last) = kp.split_at(kp.len() - 1);
            let full: Vec<String> = cur_path.iter().chain(pref.iter()).cloned().collect();
            let parent = navigate_or_create_table(&mut root, &full)?;
            if parent.contains_key(&last[0]) {
                return Err(ParseError {
                    msg: format!("duplicate key `{}`", last[0]),
                    line: p.line,
                });
            }
            parent.insert(last[0].clone(), val);
        }
    }
    Ok(Value::Table(root))
}

fn parse_key_path(p: &mut P) -> Result<Vec<String>, ParseError> {
    let mut parts = Vec::new();
    loop {
        p.eat_inline_ws();
        parts.push(parse_single_key(p)?);
        p.eat_inline_ws();
        if p.peek() == Some(b'.') { p.bump(); } else { break; }
    }
    Ok(parts)
}

fn parse_single_key(p: &mut P) -> Result<String, ParseError> {
    match p.peek() {
        Some(b'"') => { p.bump(); read_basic_string_body(p, b'"') }
        Some(b'\'') => { p.bump(); read_literal_string_body(p, b'\'') }
        _ => {
            let start = p.i;
            while let Some(b) = p.peek() {
                if b.is_ascii_alphanumeric() || b == b'_' || b == b'-' { p.bump(); }
                else { break; }
            }
            if p.i == start {
                return Err(ParseError {
                    msg: "expected an equals, found an identifier".into(),
                    line: p.line,
                });
            }
            let s = std::str::from_utf8(&p.s[start..p.i])
                .map_err(|_| ParseError { msg: "invalid utf-8 key".into(), line: p.line })?;
            Ok(s.to_string())
        }
    }
}

fn parse_value(p: &mut P) -> Result<Value, ParseError> {
    p.eat_inline_ws();
    match p.peek() {
        Some(b'"') => {
            if p.peek_at(1) == Some(b'"') && p.peek_at(2) == Some(b'"') {
                p.i += 3;
                if p.peek() == Some(b'\r') { p.bump(); }
                if p.peek() == Some(b'\n') { p.bump(); }
                read_multiline_basic(p).map(Value::String)
            } else {
                p.bump();
                read_basic_string_body(p, b'"').map(Value::String)
            }
        }
        Some(b'\'') => {
            if p.peek_at(1) == Some(b'\'') && p.peek_at(2) == Some(b'\'') {
                p.i += 3;
                if p.peek() == Some(b'\r') { p.bump(); }
                if p.peek() == Some(b'\n') { p.bump(); }
                read_multiline_literal(p).map(Value::String)
            } else {
                p.bump();
                read_literal_string_body(p, b'\'').map(Value::String)
            }
        }
        Some(b'[') => {
            p.bump();
            let mut arr = Vec::new();
            loop {
                p.eat_ws_and_comments();
                if p.peek() == Some(b']') { p.bump(); break; }
                let v = parse_value(p)?;
                arr.push(v);
                p.eat_ws_and_comments();
                if p.peek() == Some(b',') { p.bump(); p.eat_ws_and_comments(); }
                else if p.peek() == Some(b']') { p.bump(); break; }
                else { return p.err("expected `,` or `]`"); }
            }
            Ok(Value::Array(arr))
        }
        Some(b'{') => {
            p.bump();
            let mut t = BTreeMap::new();
            loop {
                p.eat_inline_ws();
                if p.peek() == Some(b'}') { p.bump(); break; }
                let kp = parse_key_path(p)?;
                p.eat_inline_ws();
                if p.peek() != Some(b'=') { return p.err("expected `=`"); }
                p.bump();
                p.eat_inline_ws();
                let v = parse_value(p)?;
                let (pref, last) = kp.split_at(kp.len() - 1);
                let parent = navigate_or_create_table(&mut t, pref)?;
                parent.insert(last[0].clone(), v);
                p.eat_inline_ws();
                if p.peek() == Some(b',') { p.bump(); }
                else if p.peek() == Some(b'}') { p.bump(); break; }
                else { return p.err("expected `,` or `}`"); }
            }
            Ok(Value::Table(t))
        }
        Some(b't') if p.s[p.i..].starts_with(b"true") => { p.i += 4; Ok(Value::Boolean(true)) }
        Some(b'f') if p.s[p.i..].starts_with(b"false") => { p.i += 5; Ok(Value::Boolean(false)) }
        Some(b) if b == b'+' || b == b'-' || b.is_ascii_digit() => {
            let start = p.i;
            if b == b'+' || b == b'-' { p.bump(); }
            while let Some(b) = p.peek() {
                if b.is_ascii_digit() || b == b'_' { p.bump(); } else { break; }
            }
            let raw = std::str::from_utf8(&p.s[start..p.i]).unwrap();
            let clean: String = raw.chars().filter(|c| *c != '_').collect();
            let n: i64 = clean.parse().map_err(|_| ParseError {
                msg: format!("invalid integer {:?}", raw), line: p.line,
            })?;
            Ok(Value::Integer(n))
        }
        _ => p.err("expected a value"),
    }
}

fn read_basic_string_body(p: &mut P, q: u8) -> Result<String, ParseError> {
    let mut out = String::new();
    loop {
        let b = p.peek().ok_or_else(|| ParseError {
            msg: "unterminated string".into(), line: p.line,
        })?;
        if b == q { p.bump(); return Ok(out); }
        if b == b'\n' { return p.err("newline in basic string"); }
        if b == b'\\' {
            p.bump();
            let c = p.peek().ok_or_else(|| ParseError {
                msg: "bad escape".into(), line: p.line,
            })?;
            match c {
                b'\\' => { out.push('\\'); p.bump(); }
                b'"' => { out.push('"'); p.bump(); }
                b'\'' => { out.push('\''); p.bump(); }
                b'n' => { out.push('\n'); p.bump(); }
                b'r' => { out.push('\r'); p.bump(); }
                b't' => { out.push('\t'); p.bump(); }
                b'b' => { out.push('\x08'); p.bump(); }
                b'f' => { out.push('\x0c'); p.bump(); }
                b'0' => { out.push('\0'); p.bump(); }
                b'u' | b'U' => {
                    p.bump();
                    let n = if c == b'u' { 4 } else { 8 };
                    let hex = std::str::from_utf8(&p.s[p.i..p.i+n])
                        .map_err(|_| ParseError { msg: "bad unicode".into(), line: p.line })?;
                    let code = u32::from_str_radix(hex, 16)
                        .map_err(|_| ParseError { msg: "bad unicode".into(), line: p.line })?;
                    if let Some(c) = char::from_u32(code) { out.push(c); }
                    p.i += n;
                }
                _ => return p.err("bad escape"),
            }
        } else {
            // read a UTF-8 char
            let start = p.i;
            p.bump();
            // account for multi-byte
            while p.i < p.s.len() && (p.s[p.i] & 0b1100_0000) == 0b1000_0000 {
                p.i += 1;
            }
            out.push_str(std::str::from_utf8(&p.s[start..p.i]).unwrap_or(""));
        }
    }
}

fn read_literal_string_body(p: &mut P, q: u8) -> Result<String, ParseError> {
    let mut out = String::new();
    loop {
        let b = p.peek().ok_or_else(|| ParseError {
            msg: "unterminated literal string".into(), line: p.line,
        })?;
        if b == q { p.bump(); return Ok(out); }
        if b == b'\n' { return p.err("newline in literal string"); }
        let start = p.i;
        p.bump();
        while p.i < p.s.len() && (p.s[p.i] & 0b1100_0000) == 0b1000_0000 { p.i += 1; }
        out.push_str(std::str::from_utf8(&p.s[start..p.i]).unwrap_or(""));
    }
}

fn read_multiline_basic(p: &mut P) -> Result<String, ParseError> {
    let mut out = String::new();
    loop {
        if p.peek() == Some(b'"') && p.peek_at(1) == Some(b'"') && p.peek_at(2) == Some(b'"') {
            p.i += 3;
            // up to 2 trailing quotes could be part of the content
            if p.peek() == Some(b'"') { out.push('"'); p.bump();
                if p.peek() == Some(b'"') { out.push('"'); p.bump(); }
            }
            return Ok(out);
        }
        let b = p.peek().ok_or_else(|| ParseError {
            msg: "unterminated multiline basic string".into(), line: p.line,
        })?;
        if b == b'\\' {
            p.bump();
            let c = p.peek().ok_or_else(|| ParseError {
                msg: "bad escape".into(), line: p.line,
            })?;
            match c {
                b'\\' => { out.push('\\'); p.bump(); }
                b'"' => { out.push('"'); p.bump(); }
                b'\'' => { out.push('\''); p.bump(); }
                b'n' => { out.push('\n'); p.bump(); }
                b'r' => { out.push('\r'); p.bump(); }
                b't' => { out.push('\t'); p.bump(); }
                b'\n' | b' ' | b'\t' | b'\r' => {
                    while matches!(p.peek(), Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r')) { p.bump(); }
                }
                _ => return p.err("bad escape"),
            }
        } else {
            let start = p.i;
            p.bump();
            while p.i < p.s.len() && (p.s[p.i] & 0b1100_0000) == 0b1000_0000 { p.i += 1; }
            out.push_str(std::str::from_utf8(&p.s[start..p.i]).unwrap_or(""));
        }
    }
}

fn read_multiline_literal(p: &mut P) -> Result<String, ParseError> {
    let mut out = String::new();
    loop {
        if p.peek() == Some(b'\'') && p.peek_at(1) == Some(b'\'') && p.peek_at(2) == Some(b'\'') {
            p.i += 3;
            if p.peek() == Some(b'\'') { out.push('\''); p.bump();
                if p.peek() == Some(b'\'') { out.push('\''); p.bump(); }
            }
            return Ok(out);
        }
        let b = p.peek().ok_or_else(|| ParseError {
            msg: "unterminated multiline literal string".into(), line: p.line,
        })?;
        let _ = b;
        let start = p.i;
        p.bump();
        while p.i < p.s.len() && (p.s[p.i] & 0b1100_0000) == 0b1000_0000 { p.i += 1; }
        out.push_str(std::str::from_utf8(&p.s[start..p.i]).unwrap_or(""));
    }
}

fn navigate_or_create_table<'a>(
    root: &'a mut BTreeMap<String, Value>,
    path: &[String],
) -> Result<&'a mut BTreeMap<String, Value>, ParseError> {
    let mut cur = root;
    for part in path {
        let entry = cur.entry(part.clone()).or_insert_with(|| Value::Table(BTreeMap::new()));
        match entry {
            Value::Table(t) => { cur = t; }
            Value::Array(a) => {
                let last = a.last_mut();
                match last {
                    Some(Value::Table(t)) => cur = t,
                    _ => return Err(ParseError { msg: "array element not a table".into(), line: 0 }),
                }
            }
            _ => return Err(ParseError {
                msg: format!("key `{}` is not a table", part), line: 0,
            }),
        }
    }
    Ok(cur)
}

// ---- Emitters ----

pub fn emit_key(s: &str) -> String {
    let bare = !s.is_empty() && s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-');
    if bare { s.to_string() } else { emit_basic_string(s) }
}

fn emit_basic_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                use std::fmt::Write as _;
                let _ = write!(out, "\\u{:04X}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Choose literal single-quoted for friendly values, multi-line ''' for newlines,
/// else basic string.
pub fn emit_string(s: &str) -> String {
    let has_nl = s.contains('\n');
    let has_sq = s.contains('\'');
    let has_bad_ctrl = s.chars().any(|c|
        (c as u32) < 0x20 && c != '\n' && c != '\t'
    );

    if has_nl {
        if !s.contains("'''") && !has_bad_ctrl {
            let mut out = String::from("'''\n");
            out.push_str(s);
            out.push_str("'''");
            return out;
        }
        return emit_basic_string(s);
    }

    if !has_sq && !has_bad_ctrl {
        let mut out = String::from("'");
        out.push_str(s);
        out.push('\'');
        return out;
    }
    emit_basic_string(s)
}

/// Emit a string-array assignment line(s) for key `name`.
pub fn emit_string_array(name: &str, items: &[String]) -> String {
    match items.len() {
        0 => format!("{} = []\n", emit_key(name)),
        1 => format!("{} = [{}]\n", emit_key(name), emit_string(&items[0])),
        _ => {
            let mut s = format!("{} = [\n", emit_key(name));
            for it in items {
                s.push_str(&format!("    {},\n", emit_string(it)));
            }
            s.push_str("]\n");
            s
        }
    }
}
