use crate::toml_val::{self, Value};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

#[derive(Clone)]
pub struct Script {
    pub alias: String,
    pub command: String,
    pub description: Option<String>,
    pub tags: Option<Vec<String>>,
}

pub struct Defaults {
    pub interpreter: Option<Vec<String>>,
    pub command_width: Option<i64>,
}

pub struct Config {
    pub scripts: BTreeMap<String, Script>,
    pub defaults: Defaults,
    pub path: PathBuf,
}

pub enum LoadError {
    Io(PathBuf, std::io::Error),
    Toml(PathBuf, String),
    Shape(PathBuf, String),
}

pub fn default_config_path() -> Option<PathBuf> {
    if let Ok(v) = std::env::var("PIER_CONFIG_PATH") {
        if !v.is_empty() { return Some(PathBuf::from(v)); }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let p = cwd.join("pier.toml");
        if p.exists() { return Some(p); }
    }
    let xdg_cfg = std::env::var("XDG_CONFIG_HOME").ok()
        .filter(|s| !s.is_empty())
        .map(PathBuf::from)
        .or_else(|| std::env::var("HOME").ok().map(|h| PathBuf::from(h).join(".config")));
    if let Some(xdg) = &xdg_cfg {
        for c in [xdg.join("pier/config.toml"), xdg.join("pier/config"), xdg.join("pier.toml")] {
            if c.exists() { return Some(c); }
        }
    }
    if let Ok(h) = std::env::var("HOME") {
        let h = PathBuf::from(h);
        for c in [h.join(".pier.toml"), h.join(".pier")] {
            if c.exists() { return Some(c); }
        }
    }
    None
}

pub fn load_from(path: &Path) -> Result<Config, LoadError> {
    let contents = std::fs::read_to_string(path)
        .map_err(|e| LoadError::Io(path.to_path_buf(), e))?;
    let val = toml_val::parse(&contents)
        .map_err(|e| LoadError::Toml(path.to_path_buf(), e.to_string()))?;
    build(path, val)
}

fn build(path: &Path, val: Value) -> Result<Config, LoadError> {
    let tbl = if let Value::Table(t) = &val { t.clone() } else {
        return Err(LoadError::Shape(path.to_path_buf(), "root is not a table".into()));
    };

    let mut scripts = BTreeMap::new();
    if let Some(Value::Table(s)) = tbl.get("scripts") {
        for (k, v) in s {
            let st = match v {
                Value::Table(st) => st,
                other => {
                    return Err(LoadError::Shape(
                        path.to_path_buf(),
                        format!("invalid type: {} {}, expected struct Script for key `scripts.{}`",
                                other.type_name(), other.display_inline(), k),
                    ));
                }
            };
            let command = match st.get("command") {
                Some(Value::String(s)) => s.clone(),
                Some(other) => return Err(LoadError::Shape(
                    path.to_path_buf(),
                    format!("invalid type: {} {}, expected string for key `scripts.{}.command`",
                            other.type_name(), other.display_inline(), k),
                )),
                None => return Err(LoadError::Shape(
                    path.to_path_buf(),
                    format!("missing field `command` for key `scripts.{}`", k),
                )),
            };
            let description = match st.get("description") {
                Some(Value::String(s)) => Some(s.clone()),
                Some(other) => return Err(LoadError::Shape(
                    path.to_path_buf(),
                    format!("invalid type: {} {}, expected string for key `scripts.{}.description`",
                            other.type_name(), other.display_inline(), k),
                )),
                None => None,
            };
            let tags = match st.get("tags") {
                Some(Value::Array(a)) => {
                    let mut v = Vec::with_capacity(a.len());
                    for e in a {
                        if let Value::String(s) = e { v.push(s.clone()); }
                        else {
                            return Err(LoadError::Shape(
                                path.to_path_buf(),
                                format!("invalid tag type for key `scripts.{}.tags`", k),
                            ));
                        }
                    }
                    Some(v)
                }
                Some(_) => return Err(LoadError::Shape(
                    path.to_path_buf(),
                    format!("invalid type for `scripts.{}.tags`", k),
                )),
                None => None,
            };
            scripts.insert(k.clone(), Script {
                alias: k.clone(), command, description, tags,
            });
        }
    }

    let defaults = if let Some(Value::Table(d)) = tbl.get("default") {
        let interpreter = match d.get("interpreter") {
            None => None,
            Some(Value::Array(a)) => {
                let mut v = Vec::new();
                for e in a {
                    if let Value::String(s) = e { v.push(s.clone()); }
                    else {
                        return Err(LoadError::Shape(
                            path.to_path_buf(),
                            "invalid interpreter element".into(),
                        ));
                    }
                }
                Some(v)
            }
            Some(other) => {
                return Err(LoadError::Shape(
                    path.to_path_buf(),
                    format!("invalid type: {} {}, expected a sequence for key `default.interpreter`",
                            other.type_name(), other.display_inline()),
                ));
            }
        };
        let command_width = match d.get("command_width") {
            None => None,
            Some(Value::Integer(i)) => Some(*i),
            Some(_) => return Err(LoadError::Shape(path.to_path_buf(),
                "invalid command_width".into())),
        };
        Defaults { interpreter, command_width }
    } else {
        Defaults { interpreter: None, command_width: None }
    };

    Ok(Config { scripts, defaults, path: path.to_path_buf() })
}

pub fn serialize(cfg: &Config) -> String {
    let mut out = String::new();
    let mut first = true;
    for s in cfg.scripts.values() {
        if !first { out.push('\n'); }
        first = false;
        out.push_str(&format!("[scripts.{}]\n", toml_val::emit_key(&s.alias)));
        out.push_str(&format!("command = {}\n", toml_val::emit_string(&s.command)));
        if let Some(d) = &s.description {
            out.push_str(&format!("description = {}\n", toml_val::emit_string(d)));
        }
        if let Some(tags) = &s.tags {
            out.push_str(&toml_val::emit_string_array("tags", tags));
        }
    }
    if !first { out.push('\n'); }
    // Always emit [default] (even if empty).
    out.push_str("[default]\n");
    if let Some(interp) = &cfg.defaults.interpreter {
        out.push_str(&toml_val::emit_string_array("interpreter", interp));
    }
    if let Some(w) = cfg.defaults.command_width {
        out.push_str(&format!("command_width = {}\n", w));
    }

    // BUT: when scripts is empty but the input had `[scripts]` table, emit empty section.
    // Simpler heuristic: if scripts empty, still need to know whether `[scripts]` existed.
    // We'll handle this at caller by providing whether [scripts] header was present.
    out
}

/// Variation that emits an empty `[scripts]` block when there are no scripts.
pub fn serialize_with_empty_scripts_header(cfg: &Config) -> String {
    let mut out = String::new();
    if cfg.scripts.is_empty() {
        out.push_str("[scripts]\n\n");
        out.push_str("[default]\n");
        if let Some(interp) = &cfg.defaults.interpreter {
            out.push_str(&toml_val::emit_string_array("interpreter", interp));
        }
        if let Some(w) = cfg.defaults.command_width {
            out.push_str(&format!("command_width = {}\n", w));
        }
        return out;
    }
    serialize(cfg)
}
