mod toml_val;
mod config;
mod help;
mod editor;

use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use crate::config::{Config, Script};

const SUBCOMMANDS: &[&str] = &[
    "add", "config-init", "init", "copy", "cp", "edit", "help", "list", "ls",
    "move", "mv", "rename", "remove", "rm", "run", "show",
];

fn print_err(msg: impl AsRef<str>) {
    eprintln!("error: {}", msg.as_ref());
}

fn usage_root_missing_alias() -> String {
    let mut s = String::new();
    s.push_str("USAGE:\n");
    s.push_str("    executable <alias> --config-file <path>\n\n");
    s.push_str("For more information try --help");
    s
}

fn usage_root_unknown() -> String {
    let mut s = String::new();
    s.push_str("USAGE:\n");
    s.push_str("    executable [FLAGS] [OPTIONS] <alias> [args]...\n");
    s.push_str("    executable [FLAGS] [OPTIONS] <SUBCOMMAND>\n\n");
    s.push_str("For more information try --help");
    s
}

fn main() -> ExitCode {
    let argv: Vec<String> = std::env::args().collect();
    match run(&argv[1..]) {
        Ok(code) => code,
        Err(code) => code,
    }
}

fn run(args: &[String]) -> Result<ExitCode, ExitCode> {
    // Root-level parsing.
    // Accepts: [-h|--help], [-V|--version], [-v|--verbose], [-c|--config-file <path>],
    // then either a <SUBCOMMAND> [...] or an <alias> [args...].
    let mut i = 0;
    let mut verbose = false;
    let mut config_file: Option<String> = None;

    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-h" => { print!("{}", help::root_help_short()); return Ok(ExitCode::SUCCESS); }
            "--help" => { print!("{}", help::root_help_long()); return Ok(ExitCode::SUCCESS); }
            "-V" | "--version" => { println!("{}", help::VERSION); return Ok(ExitCode::SUCCESS); }
            "-v" | "--verbose" => {
                if verbose {
                    eprintln!("error: The argument '--verbose' was provided more than once, but cannot be used multiple times\n");
                    eprintln!("USAGE:");
                    eprintln!("    executable <alias> --config-file <path> --verbose\n");
                    eprintln!("For more information try --help");
                    return Err(ExitCode::from(1));
                }
                verbose = true;
                i += 1;
            }
            "-c" | "--config-file" => {
                if i + 1 >= args.len() {
                    eprintln!("error: The argument '--config-file <path>' requires a value but none was supplied\n");
                    eprintln!("USAGE:");
                    eprintln!("    executable <alias> --config-file <path>\n");
                    eprintln!("For more information try --help");
                    return Err(ExitCode::from(1));
                }
                config_file = Some(args[i+1].clone());
                i += 2;
            }
            s if s.starts_with("--config-file=") => {
                config_file = Some(s["--config-file=".len()..].to_string());
                i += 1;
            }
            "--" => { i += 1; break; }
            _ => break,
        }
    }

    let remaining = &args[i..];
    if remaining.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <alias>\n");
        eprintln!("{}", usage_root_missing_alias());
        return Err(ExitCode::from(1));
    }

    let first = &remaining[0];
    let rest = &remaining[1..];

    // Subcommand dispatch.
    match first.as_str() {
        "help" => return cmd_help(rest),
        "add" => return cmd_add(config_file.as_deref(), rest),
        "config-init" | "init" => return cmd_config_init(config_file.as_deref(), rest),
        "copy" | "cp" => return cmd_copy(config_file.as_deref(), rest),
        "move" | "mv" | "rename" => return cmd_move(config_file.as_deref(), rest),
        "edit" => return cmd_edit(config_file.as_deref(), rest),
        "list" | "ls" => return cmd_list(config_file.as_deref(), rest),
        "remove" | "rm" => return cmd_remove(config_file.as_deref(), rest),
        "run" => return cmd_run(config_file.as_deref(), rest),
        "show" => return cmd_show(config_file.as_deref(), rest),
        _ => {}
    }

    // Otherwise treat as top-level `alias [args...]`.
    if first.starts_with('-') {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n", first);
        eprintln!("{}", usage_root_unknown());
        return Err(ExitCode::from(1));
    }

    run_alias(config_file.as_deref(), first, rest)
}

// ---- Utility: help subcommand ----

fn cmd_help(args: &[String]) -> Result<ExitCode, ExitCode> {
    // `help` with no args prints top-level short help.
    if args.is_empty() {
        print!("{}", help::root_help_short());
        return Ok(ExitCode::SUCCESS);
    }
    let name = &args[0];
    let text = match name.as_str() {
        "add" => help::add_help_short(),
        "config-init" | "init" => help::config_init_help_short(),
        "copy" | "cp" => help::copy_help_short(),
        "edit" => help::edit_help_short(),
        "list" | "ls" => help::list_help_short(),
        "move" | "mv" | "rename" => help::move_help_short(),
        "remove" | "rm" => help::remove_help_short(),
        "run" => help::run_help_short(),
        "show" => help::show_help_short(),
        "help" => help::help_help_short(),
        _ => {
            eprintln!("error: The subcommand '{}' wasn't recognized", name);
            eprintln!("\nUSAGE:");
            eprintln!("    executable help [subcommand]...\n");
            eprintln!("For more information try --help");
            return Err(ExitCode::from(1));
        }
    };
    print!("{}", text);
    Ok(ExitCode::SUCCESS)
}

fn handle_help_long_flags(args: &[String], short_help: impl Fn()->String, long_help: impl Fn()->String) -> Option<ExitCode> {
    for a in args {
        if a == "-h" { print!("{}", short_help()); return Some(ExitCode::SUCCESS); }
        if a == "--help" { print!("{}", long_help()); return Some(ExitCode::SUCCESS); }
        if a == "-V" || a == "--version" { println!("executable-unknown 0.1.6"); return Some(ExitCode::SUCCESS); }
    }
    None
}

// ---- Config loading helpers ----

fn resolve_config_path(override_path: Option<&str>) -> Result<PathBuf, ExitCode> {
    if let Some(p) = override_path { return Ok(PathBuf::from(p)); }
    match config::default_config_path() {
        Some(p) => Ok(p),
        None => {
            print_err("No default config file found. See help for more info.");
            Err(ExitCode::from(1))
        }
    }
}

fn load_config(override_path: Option<&str>) -> Result<Config, ExitCode> {
    let path = resolve_config_path(override_path)?;
    match config::load_from(&path) {
        Ok(c) => Ok(c),
        Err(e) => {
            match e {
                config::LoadError::Io(p, e) => {
                    print_err(format!("Unable to read config from file {}: {} ", p.display(), e));
                }
                config::LoadError::Toml(p, m) => {
                    print_err(format!("Unable to parse toml config from file {}: {}", p.display(), m));
                }
                config::LoadError::Shape(p, m) => {
                    print_err(format!("Unable to parse toml config from file {}: {}", p.display(), m));
                }
            }
            Err(ExitCode::from(1))
        }
    }
}

fn save_config(cfg: &Config, empty_scripts_header: bool) -> Result<(), ExitCode> {
    let content = if empty_scripts_header {
        config::serialize_with_empty_scripts_header(cfg)
    } else {
        config::serialize(cfg)
    };
    if let Err(e) = std::fs::write(&cfg.path, content) {
        print_err(format!("Failed to write config. {} (os error {})",
                          e.to_string(), e.raw_os_error().unwrap_or(0)));
        return Err(ExitCode::from(1));
    }
    Ok(())
}

// ---- Command: config-init ----

fn cmd_config_init(override_path: Option<&str>, args: &[String]) -> Result<ExitCode, ExitCode> {
    if let Some(c) = handle_help_long_flags(args,
        help::config_init_help_short, help::config_init_help_long) { return Ok(c); }
    if !args.is_empty() {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n", args[0]);
        eprintln!("USAGE:");
        eprintln!("    executable config-init\n");
        eprintln!("For more information try --help");
        return Err(ExitCode::from(1));
    }

    // Determine destination path.
    let path: PathBuf = if let Some(p) = override_path {
        PathBuf::from(p)
    } else if let Ok(v) = std::env::var("PIER_CONFIG_PATH") {
        if v.is_empty() { default_config_init_path() } else { PathBuf::from(v) }
    } else {
        default_config_init_path()
    };

    if path.exists() {
        print_err(format!("Cannot initialize config at {}, file already exists.", path.display()));
        return Err(ExitCode::from(1));
    }

    // Ensure parent directory exists.
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() && !parent.exists() {
            if let Err(e) = std::fs::create_dir_all(parent) {
                print_err(format!("Failed to create directory. {} (os error {})",
                    e.to_string(), e.raw_os_error().unwrap_or(0)));
                return Err(ExitCode::from(1));
            }
        }
    }

    let mut cfg = Config {
        scripts: std::collections::BTreeMap::new(),
        defaults: config::Defaults { interpreter: None, command_width: None },
        path: path.clone(),
    };
    let hello = Script {
        alias: "hello-pier".into(),
        command: "echo Hello, Pier!".into(),
        description: Some("This is an example command.".into()),
        tags: None,
    };
    cfg.scripts.insert(hello.alias.clone(), hello);
    save_config(&cfg, false)?;
    println!("Added hello-pier");
    Ok(ExitCode::SUCCESS)
}

fn default_config_init_path() -> PathBuf {
    // Default target for config-init: $XDG_CONFIG_HOME/pier/config.toml,
    // falling back to $HOME/.config/pier/config.toml.
    let xdg = std::env::var("XDG_CONFIG_HOME").ok()
        .filter(|s| !s.is_empty())
        .map(PathBuf::from)
        .or_else(|| std::env::var("HOME").ok().map(|h| PathBuf::from(h).join(".config")))
        .unwrap_or_else(|| PathBuf::from("."));
    xdg.join("pier").join("config.toml")
}

// ---- Command: list ----

fn cmd_list(override_path: Option<&str>, args: &[String]) -> Result<ExitCode, ExitCode> {
    if let Some(c) = handle_help_long_flags(args, help::list_help_short, help::list_help_long) { return Ok(c); }
    let mut list_aliases = false;
    let mut cmd_full = false;
    let mut cmd_width: Option<i64> = None;
    let mut filter_tags: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-q" | "--list_aliases" => { list_aliases = true; i += 1; }
            "-l" | "--cmd_full" => { cmd_full = true; i += 1; }
            "-c" | "--cmd_width" => {
                if i + 1 >= args.len() {
                    print_err("The argument '--cmd_width <cmd-width>' requires a value but none was supplied");
                    return Err(ExitCode::from(1));
                }
                match args[i+1].parse::<i64>() {
                    Ok(n) => { cmd_width = Some(n); }
                    Err(_) => {
                        print_err("Invalid value for '--cmd_width <cmd-width>': invalid digit found in string");
                        return Err(ExitCode::from(1));
                    }
                }
                i += 2;
            }
            s if s.starts_with("--cmd_width=") => {
                match s["--cmd_width=".len()..].parse::<i64>() {
                    Ok(n) => { cmd_width = Some(n); i += 1; }
                    Err(_) => {
                        print_err("Invalid value for '--cmd_width <cmd-width>': invalid digit found in string");
                        return Err(ExitCode::from(1));
                    }
                }
            }
            "-t" | "--tag" => {
                // Consume subsequent positional values until next flag.
                i += 1;
                while i < args.len() && !args[i].starts_with('-') {
                    filter_tags.push(args[i].clone());
                    i += 1;
                }
            }
            other => {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n", other);
                eprintln!("USAGE:");
                eprintln!("    executable list [FLAGS] [OPTIONS]\n");
                eprintln!("For more information try --help");
                return Err(ExitCode::from(1));
            }
        }
    }

    let cfg = load_config(override_path)?;
    if cfg.scripts.is_empty() {
        print_err("No scripts exist. Would you like to add a new script?");
        return Err(ExitCode::from(1));
    }

    let effective_width = cmd_width.or(cfg.defaults.command_width);

    // Collect scripts (alphabetical by alias, BTreeMap already sorted).
    // If filter_tags is empty, list all. Else apply filter.
    let scripts: Vec<Script> = if filter_tags.is_empty() {
        cfg.scripts.values().cloned().collect()
    } else {
        let mut out = Vec::new();
        for s in cfg.scripts.values() {
            for t in &filter_tags {
                if let Some(tags) = &s.tags {
                    if tags.iter().any(|x| x == t) {
                        out.push(s.clone());
                    }
                }
            }
        }
        out
    };

    if list_aliases {
        for s in &scripts {
            println!("{}", s.alias);
        }
        return Ok(ExitCode::SUCCESS);
    }

    // Build rows: each script -> one or more rows (alias, tags, cmd_line, desc)
    // Only the first row of a multi-line command carries alias/tags/desc.
    struct Row { alias: String, tags: String, cmd: String, desc: String }
    let mut rows: Vec<Row> = Vec::new();

    for s in &scripts {
        let tags = s.tags.as_ref().map(|v| v.join(",")).unwrap_or_default();
        let desc = s.description.clone().unwrap_or_default();

        if cmd_full {
            // Keep all lines, but drop trailing empty lines.
            let mut lines: Vec<String> = s.command.split('\n').map(|s| s.to_string()).collect();
            while matches!(lines.last(), Some(x) if x.is_empty()) { lines.pop(); }
            if lines.is_empty() { lines.push(String::new()); }
            for (i, l) in lines.iter().enumerate() {
                if i == 0 {
                    rows.push(Row { alias: s.alias.clone(), tags: tags.clone(), cmd: l.clone(), desc: desc.clone() });
                } else {
                    rows.push(Row { alias: String::new(), tags: String::new(), cmd: l.clone(), desc: String::new() });
                }
            }
        } else {
            // First line only, possibly truncated to width.
            let first_line = s.command.split('\n').next().unwrap_or("");
            let shown = match effective_width {
                Some(w) if w >= 0 => first_line.chars().take(w as usize).collect::<String>(),
                _ => first_line.to_string(),
            };
            rows.push(Row { alias: s.alias.clone(), tags: tags, cmd: shown, desc });
        }
    }

    // Compute column widths.
    let headers = ["Alias", "Tags", "Command", "Description"];
    let mut w = [headers[0].chars().count(), headers[1].chars().count(),
                 headers[2].chars().count(), headers[3].chars().count()];
    for r in &rows {
        w[0] = w[0].max(r.alias.chars().count());
        w[1] = w[1].max(r.tags.chars().count());
        w[2] = w[2].max(r.cmd.chars().count());
        w[3] = w[3].max(r.desc.chars().count());
    }

    // Total visible width = 1 + sum(w_i + 3) for i in 0..4
    let total: usize = 1 + w.iter().sum::<usize>() + 4 * 3;

    let hbar: String = "≖".repeat(total);
    println!("{}", hbar);
    println!("⋮ {} ⋮ {} ⋮ {} ⋮ {} ⋮",
        pad_right(headers[0], w[0]),
        pad_right(headers[1], w[1]),
        pad_right(headers[2], w[2]),
        pad_right(headers[3], w[3]));
    println!("{}", hbar);
    for r in &rows {
        println!("⋮ {} ⋮ {} ⋮ {} ⋮ {} ⋮",
            pad_right(&r.alias, w[0]),
            pad_right(&r.tags, w[1]),
            pad_right(&r.cmd, w[2]),
            pad_right(&r.desc, w[3]));
    }
    println!("{}", hbar);
    Ok(ExitCode::SUCCESS)
}

fn pad_right(s: &str, w: usize) -> String {
    let n = s.chars().count();
    if n >= w { return s.to_string(); }
    let mut out = String::from(s);
    for _ in 0..(w - n) { out.push(' '); }
    out
