    }
}

fn load_config(override_path: Option<&str>) -> Result<Config, ExitCode> {
    let path = resolve_config_path(override_path)?;
    match config::load_from(&path) {
        Ok(c) => Ok(c),
        Err(e) => {
            match e {
                config::LoadError::Io(p, e) => {
                    print_err(format!("Unable to read config from file {}: {} ", p.display(), e));
                }
                config::LoadError::Toml(p, m) => {
                    print_err(format!("Unable to parse toml config from file {}: {}", p.display(), m));
