        eprintln!("USAGE:");
        eprintln!("    executable remove <alias>\n");
        eprintln!("For more information try --help");
        return Err(ExitCode::from(1));
    }
    let mut cfg = load_config(override_path)?;
    let alias = &args[0];
    if cfg.scripts.remove(alias).is_none() {
        print_err(format!("AliasNotFound: No script found by alias {}", alias));
        return Err(ExitCode::from(1));
    }
    // If scripts is now empty, emit `[scripts]` header block.
    let empty = cfg.scripts.is_empty();
