// ---- Command: run ----

fn cmd_run(override_path: Option<&str>, args: &[String]) -> Result<ExitCode, ExitCode> {
    if let Some(c) = handle_help_long_flags(args, help::run_help_short, help::run_help_long) { return Ok(c); }
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <alias>\n");
        eprintln!("USAGE:");
        eprintln!("    executable run <alias> [args]...\n");
        eprintln!("For more information try --help");
        return Err(ExitCode::from(1));
    }
    run_alias(override_path, &args[0], &args[1..])
}

fn run_alias(override_path: Option<&str>, alias: &str, args: &[String]) -> Result<ExitCode, ExitCode> {
    let cfg = load_config(override_path)?;
    let script = match cfg.scripts.get(alias) {
        Some(s) => s.clone(),
        None => {
            print_err(format!("AliasNotFound: No script found by alias {}", alias));
            return Err(ExitCode::from(1));
        }
    };
    // Build command line.
    let interp = cfg.defaults.interpreter.clone().unwrap_or_else(|| vec!["sh".into(), "-c".into()]);
    if interp.is_empty() {
        print_err("Empty interpreter configured");
        return Err(ExitCode::from(1));
    }
    let (program, rest_interp) = interp.split_first().unwrap();
    let mut cmd = std::process::Command::new(program);
    for a in rest_interp { cmd.arg(a); }
    cmd.arg(&script.command);
    cmd.arg(alias);
    for a in args { cmd.arg(a); }
    cmd.stdout(std::process::Stdio::inherit());
    cmd.stderr(std::process::Stdio::piped());

    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => {
            print_err(format!("Failed to run interpreter: {}", e));
            return Err(ExitCode::from(1));
        }
    };
    // Read stderr to completion.
    let mut stderr_buf = Vec::new();
    if let Some(mut s) = child.stderr.take() {
        use std::io::Read;
        let _ = s.read_to_end(&mut stderr_buf);
    }
    let status = match child.wait() {
        Ok(s) => s,
        Err(e) => {
            print_err(format!("Failed to wait for interpreter: {}", e));
            return Err(ExitCode::from(1));
        }
    };

    // Emit captured stderr (matching eprintln! which appends a newline).
    if !stderr_buf.is_empty() {
        let _ = std::io::stderr().write_all(&stderr_buf);
        let _ = writeln!(std::io::stderr());
    }

    let code = status.code().unwrap_or(1) as u8;
    Ok(ExitCode::from(code))
}
